class EnvVarCheck
{
    void CheckFlag()
    {
        // On Linux, set via: export MY_FLAG=""
        // .NET 9 breaking change: empty env vars are no longer treated as unset.
        // Use a method that distinguishes "not set" from "explicitly empty".
        var val = Environment.GetEnvironmentVariable("MY_FLAG");
        if (!IsEnvironmentVariableSet("MY_FLAG"))
        {
            Console.WriteLine("MY_FLAG not set, using default");
        }
    }

    /// <summary>
    /// In .NET 9, GetEnvironmentVariable returns "" for empty vars instead of null.
    /// To distinguish "not set" from "explicitly empty", check the raw environment.
    /// </summary>
    private static bool IsEnvironmentVariableSet(string variable)
    {
        // GetEnvironmentVariable returns null only when truly unset in .NET 9.
        // An explicitly empty variable now returns "" instead of null.
        return Environment.GetEnvironmentVariable(variable) is not null;
    }
}

